<?php require __DIR__.'/bootstrap.php';$u=require_login();$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT * FROM exclusive_videos WHERE id=? AND status='published'");$q->execute([$id]);$v=$q->fetch();if(!$v){http_response_code(404);exit('Vídeo não encontrado.');}if($u['role']==='member'&&!is_ultimate((int)$u['id'])){http_response_code(403);exit('Este vídeo é exclusivo para membros Ultimate. <a href="index.php#planos">Conhecer planos</a>');}$youtube='';if(preg_match('~(?:youtu\.be/|v=|embed/)([A-Za-z0-9_-]{6,})~',$v['video_url'],$m))$youtube=$m[1];?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($v['title'])?> — Arena</title><link rel="stylesheet" href="assets/app.css"></head><body class="anime"><?php nav($u)?><main class="watch"><p class="eyebrow">ULTIMATE EXCLUSIVO</p><h1><?=e($v['title'])?></h1><?php if($youtube):?><div class="embed"><iframe src="https://www.youtube-nocookie.com/embed/<?=e($youtube)?>" title="<?=e($v['title'])?>" allowfullscreen></iframe></div><?php else:?><video controls controlsList="nodownload" src="<?=e($v['video_url'])?>"></video><?php endif?><p class="muted"><?=nl2br(e($v['description']))?></p></main></body></html>
